#!/usr/bin/env python3
"""Generate Lesson 2 Beamer section files and speaker notes from an editable outline.
This is a new, stand-alone teaching package; no files in the user's Brain are written.
"""
from pathlib import Path
from textwrap import dedent
R=Path(__file__).resolve().parent
S=R/'lesson2/sections'; S.mkdir(parents=True,exist_ok=True)

def e(s):
    s=str(s)
    for a,b in [('\\','\\textbackslash{}'),('&','\\&'),('%','\\%'),('$','\\$'),('#','\\#'),('_','\\_'),('{','\\{'),('}','\\}')]:
        # escape in one pass? replacements braces inside commands would break. Use regex alternative below
        pass
    import re
    mp={'\\':r'\textbackslash{}','&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_','{':r'\{','}':r'\}','~':r'\textasciitilde{}','^':r'\textasciicircum{}'}
    return re.sub(r'[\\&%$#_{}~^]',lambda m:mp[m.group()],s)

def rows(x):
    return ''.join(r'\item \textbf{'+e(h)+r'.} '+e(t)+'\n' for h,t in x)

def build_one(s):
    n=s['n']; title=s['title']; kicker=s['section']; intro=s.get('intro',''); bullets=s.get('bullets',[])
    src=s.get('source','Course synthesis and verified Brain project notes')
    tag=s.get('tag','')
    if n==1:
        return r'''\begin{frame}[plain]
\begin{tikzpicture}[remember picture,overlay]
\node[anchor=center,inner sep=0] at (current page.center) {\includegraphics[width=\paperwidth,height=\paperheight]{ai-assistant-lab-original.png}};
\fill[black,opacity=.51] (current page.south west) rectangle ($(current page.south west)+(\paperwidth,2.78cm)$);
\node[anchor=south west,text width=12.3cm,align=left] at ($(current page.south west)+(.68cm,.66cm)$)
{\color{white}\fontsize{25}{30}\selectfont\bfseries From JARVIS to Your Own Second Brain\\[3pt]
\normalsize\color{white!85} Persistent memory, tools and cumulative knowledge\\[4pt]
\footnotesize\color{white!78} Agentic AI for Economic Research \quad|\quad Lesson 2 \quad|\quad Marco Le Moglie};
\end{tikzpicture}
\end{frame}
'''
    body=''
    if s.get('wide_image'):
        body+=r'\kicker{'+e(kicker)+'}\n'
        if intro:body+=r'\subt{'+e(intro)+'}\n'
        body+=r'\begin{center}\includegraphics[width=.96\textwidth,height=4.48cm,keepaspectratio]{'+s['wide_image']+r'}\end{center}'+'\n'
        body+=r'{\color{muted}\scriptsize '+e(s.get('caption','Illustrative teaching capture; not a live product screenshot.'))+r'}\par'+'\n'
        if tag:body+=r'\tagline{'+e(tag)+'}\n'
    elif s.get('image'):
        body+=r'\kicker{'+e(kicker)+'}\n'
        if intro:body+=r'\subt{'+e(intro)+'}\n'
        body+=r'\begin{columns}[T,onlytextwidth]'+'\n'
        body+=r'\column{.51\textwidth}\begin{itemize}\setlength{\itemsep}{.5em}\small'+'\n'+rows(bullets)+r'\end{itemize}'+'\n'
        body+=r'\column{.46\textwidth}'+'\n'
        body+=r'\includegraphics[width=\linewidth,height=4.75cm,keepaspectratio]{'+s['image']+r'}'+'\n'
        body+=r'\par{\color{muted}\scriptsize '+e(s.get('caption','Illustrative course image.'))+r'}\end{columns}'+'\n'
        if tag:body+=r'\tagline{'+e(tag)+'}\n'
    elif s.get('four'):
        body+=r'\kicker{'+e(kicker)+'}\n'
        if intro:body+=r'\subt{'+e(intro)+'}\n'
        for k in range(0,4,2):
            body+=r'\begin{columns}[T,onlytextwidth]\column{.485\textwidth}'+'\n'
            h,t=s['four'][k];body+=r'\sboxblue{'+e(h)+'}{'+e(t)+'}\n'
            body+=r'\column{.485\textwidth}'+'\n'
            h,t=s['four'][k+1];body+=r'\coursebox{'+e(h)+'}{'+e(t)+'}\n'
            body+=r'\end{columns}\vspace{1mm}'+'\n'
        if tag:body+=r'\tagline{'+e(tag)+'}\n'
    else:
        body+=r'\kicker{'+e(kicker)+'}\n'
        if intro:body+=r'\subt{'+e(intro)+'}\n'
        body+=r'\begin{columns}[T,onlytextwidth]\column{.565\textwidth}'+'\n'
        body+=r'\begin{itemize}\setlength{\itemsep}{.48em}\small'+'\n'+rows(bullets)+r'\end{itemize}'+'\n'
        body+=r'\column{.405\textwidth}'+'\n'
        side=s.get('side',[])
        for h,t in side:
            body+=r'\sboxblue{'+e(h)+'}{'+e(t)+'}\n'
        body+=r'\end{columns}'+'\n'
        if tag:body+=r'\tagline{'+e(tag)+'}\n'
    body+=r'\citefoot{'+e(src)+'}\n'
    return r'\begin{frame}{'+e(title)+'}\n'+body+r'\end{frame}'+'\n'

