 dict(n=24,title='Connect an AI agent safely',section='Build it',intro='The agent needs explicit filesystem access and a repeatable entry point.',bullets=[('Workspace','Open the vault folder or provide the path using the agent’s supported tools.'),('Entry point','Give BOOTSTRAP.md: where to read, how to route, what not to touch.'),('Permission scope','Read-only for initial onboarding; writes require clear approval and Git diffs.'),('Session protocol','Start from index and state; end by updating validated durable memory.')],side=[('Avoid','Granting blanket access to credentials, unrelated folders or all private documents.'),('Check','Does this agent actually see the folder? Are file modifications reversible?')],tag='The ability to read a vault is not the same as automatic memory.',source='Brain BOOTSTRAP and MEMORY_POLICY; agent filesystem docs'),
