 dict(n=37,title='Appendix: an Economics research design',section='Optional reading',intro='Separate the model effect from the additional effect of persistent memory.',bullets=[('Treatment A','Standard chatbot plus ordinary shared folders.'),('Treatment B','Chatbot with retrieval over the same research documents.'),('Treatment C','RAG plus curated core memory, wiki and consistent closeout protocol.'),('Outcomes','Completion time, correctness, token cost, error recurrence and 4-week retention.')],side=[('Design caution','Randomize teams or tasks; standardize documents; measure contamination across groups.'),('Theory','Knowledge transfer and organizational memory help explain heterogeneity.')],source='Proposed teaching exercise, not an existing published estimate'),
